   "title": "hook_ssh: identify public-door senders by ssh signature",
   "verb": {
    "allow": [],
    "asserts": "ssh",
    "chain": "verb/hook_ssh",
    "description": "Pre-turn hook. Given the decoded public payload, prints the ssh principal name if the payload is a JSON object {msg, sig} whose sig is a valid ssh-keygen -Y sign signature over msg in namespace mshkn by a key in the baked allowed_signers file. Prints nothing otherwise, leaving the sender anonymous.",
    "dockerfile": "FROM mshkn-base\nRUN apt-get update && apt-get install -y --no-install-recommends jq && rm -rf /var/lib/apt/lists/*\nRUN mkdir -p /verb\nRUN printf '%s\\n' 'mike ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIOBbG4DZGfHsMoA4BgiwFw38xyW/QE4W9T/yjQ3Zz8DY mike' > /verb/allowed_signers && chmod 0444 /verb/allowed_signers\nRUN printf '%s\\n' '#!/bin/sh' 'set -u' 'A=\"${ALLOWED:-/verb/allowed_signers}\"' 'D=\"${DEBUG:-}\"' 'W=$(mktemp -d)' 'printf %s \"$1\" | jq -j -e -r .msg > \"$W/msg\" 2>/dev/null || exit 0' 'printf %s \"$1\" | jq -j -e -r .sig 2>/dev/null | base64 -d > \"$W/sig\" 2>/dev/null || exit 0' '[ -s \"$W/sig\" ] || exit 0' 'cp \"$W/msg\" \"$W/msgnl\"; printf \"\\n\" >> \"$W/msgnl\"' 'P=$(ssh-keygen -Y find-principals -f \"$A\" -s \"$W/sig\" < \"$W/msg\" 2>/dev/null | head -n1)' '[ -n \"$D\" ] && echo \"    dbg: principals=[$P]\" >&2' '[ -n \"$P\" ] || exit 0' 'for f in \"$W/msg\" \"$W/msgnl\"; do' '  ssh-keygen -Y verify -f \"$A\" -I \"$P\" -n mshkn -s \"$W/sig\" < \"$f\" > \"$W/out\" 2>&1; rc=$?' '  [ -n \"$D\" ] && echo \"    dbg: verify $(basename \"$f\") rc=$rc out=$(tr -d \"\\n\" < \"$W/out\")\" >&2' '  if [ \"$rc\" = 0 ]; then printf %s \"$P\"; exit 0; fi' 'done' 'exit 0' > /verb/run.sh && chmod +x /verb/run.sh",
