   "title": "page_title: report the &lt;title&gt; of an http(s) page",
   "verb": {
    "allow": [
     "ssh:mike"
    ],
    "chain": "verb/page_title",
    "description": "Fetch an http(s) URL on a fresh computer and report the text of the page's <title> element. Prints the title on stdout; on failure prints a reason on stderr and exits non-zero (2 bad scheme, 3 no title, 5 fetch failed, 6 HTTP >= 400).",
    "dockerfile": "FROM mshkn-base\nRUN mkdir -p /verb && printf '#!/bin/sh\\nperl -0777 -pe \"s{<!--.*?-->}{}gs; s{<script.*?</script>}{}gis; s{<style.*?</style>}{}gis\" | tr \"\\\\n\\\\r\\\\t\" \"   \" | grep -oi \"<title[^>]*>[^<]*\" | head -n1 | sed \"s/^<[Tt][Ii][Tt][Ll][Ee][^>]*>//\" | sed -e \"s/&nbsp;/ /g\" -e \"s/&quot;/\\\\\"/g\" -e \"s/&#39;/\\\\x27/g\" -e \"s/&#x27;/\\\\x27/g\" -e \"s/&lt;/</g\" -e \"s/&gt;/>/g\" -e \"s/&amp;/\\\\&/g\" | tr -s \" \" | sed -e \"s/^ *//\" -e \"s/ *$//\"\\n' > /verb/extract.sh && chmod +x /verb/extract.sh\nRUN printf '#!/bin/sh\\nset -u\\nurl=\"$1\"\\ncase \"$url\" in\\n  http://*|https://*) ;;\\n  *) echo \"error: only http and https URLs are supported\" >&2; exit 2 ;;\\nesac\\nmeta=$(curl -sS -L --max-redirs 5 --max-time 20 --max-filesize 5000000 -o /tmp/body -w \"%%{http_code} %%{content_type}\" -A \"mshkn-page-title/1\" -H \"Accept: text/html\" \"$url\" 2>/tmp/err)\\nrc=$?\\nif [ \"$rc\" -ne 0 ]; then printf \"error: fetch failed: %%s\\\\n\" \"$(head -c 200 /tmp/err)\" >&2; exit 5; fi\\ncode=${meta%%%% *}\\nctype=${meta#* }\\nif [ \"$code\" -ge 400 ]; then printf \"error: server returned HTTP %%s\\\\n\" \"$code\" >&2; exit 6; fi\\n' > /verb/run.sh && printf 'if [ ! -s /tmp/body ]; then echo \"error: empty response body\" >&2; exit 5; fi\\nt=$(head -c 300000 /tmp/body | /verb/extract.sh || true)\\nif [ -z \"$t\" ]; then printf \"error: no non-empty <title> found (HTTP %%s, content-type %%s)\\\\n\" \"$code\" \"$ctype\" >&2; exit 3; fi\\nprintf \"%%s\\\\n\" \"$t\"\\n' >> /verb/run.sh && chmod +x /verb/run.sh",
