   "title": "count_calls: a chain-state verb that reports how many times it has successfully run",
   "verb": {
    "allow": [
     "ssh:mike"
    ],
    "chain": "verb/count_calls",
    "description": "Increment and report the number of times this verb has successfully run. Persists across invocations on its own chain state. Takes no parameters; prints the new count on stdout and nothing else.",
    "dockerfile": "FROM mshkn-base\nRUN mkdir -p /verb\nRUN printf '%s\\n' '#!/bin/sh' 'set -eu' 'STATE_DIR=${MSHKN_STATE_DIR:-/verb/state}' 'FILE=$STATE_DIR/count' 'if ! mkdir -p \"$STATE_DIR\" 2>/dev/null; then echo \"count_calls: cannot create state dir $STATE_DIR\" >&2; exit 4; fi' 'if [ -e \"$FILE\" ]; then' '  if ! n=$(cat \"$FILE\" 2>/dev/null); then echo \"count_calls: cannot read $FILE\" >&2; exit 5; fi' 'else' '  n=0' 'fi' 'case \"$n\" in *[!0-9]*) n= ;; esac' 'if [ -z \"$n\" ]; then echo \"count_calls: corrupt counter file $FILE (not a non-negative integer); leaving it untouched for root to repair\" >&2; exit 6; fi' 'n=$((n+1))' 'if ! printf \"%s\\\\n\" \"$n\" > \"$FILE.tmp\" 2>/dev/null; then echo \"count_calls: cannot write $FILE.tmp\" >&2; exit 7; fi' 'if ! mv \"$FILE.tmp\" \"$FILE\" 2>/dev/null; then echo \"count_calls: cannot commit $FILE\" >&2; exit 8; fi' 'printf \"%s\\\\n\" \"$n\"' > /verb/run.sh\nRUN chmod +x /verb/run.sh\n",
    "effect": "local",
    "entrypoint": "/verb/run.sh",
    "name": "count_calls",
